test('invoiceTotals calculates total = subtotal - discount + vat', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 17000, discount = 1700, after discount = 15300
  // vat = 15300 * 21 / 100 = 3213
  // total = 17000 - 1700 + 3213 = 18513
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.vat, 3213);
  assert.equal(totals.total, 18513);
});

