  const totals = invoiceTotals(invoice);
  // Line 1: subtotal=10000, discount=5000, after=5000, vat=1050
  // Line 2: subtotal=10000, discount=0, after=10000, vat=2100
  // total subtotal = 20000, total discount = 5000, total vat = 3150
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 5000);
  assert.equal(totals.vat, 3150);
  assert.equal(totals.total, 18150);
});

test('invoiceTotals with tier discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 }, // no explicit discount, uses 5% tier
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  // lineTotal = 17000, discount = 850, after discount = 16150
  // VAT = 16150 * 21 / 100 = 3391.5 rounds to 3392 (with roundCents banker's rounding)
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 850);
  assert.equal(totals.vat, 3392);
  assert.equal(totals.total, 18542);
});

