import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice returns an invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2024-01-15');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
});

test('createInvoice reports unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice validates issueDate format', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '01/15/2024',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r1, { ok: false, error: 'DATE_INVALID' });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r2, { ok: false, error: 'DATE_INVALID' });

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r3, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects missing lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice validates quantity is a positive integer', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(r1, { ok: false, error: 'QTY_INVALID' });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: -1 }],
  });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r3, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice validates SKU exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  };
  const originalLines = JSON.stringify(input.lines);
  createInvoice(input);
  assert.equal(JSON.stringify(input.lines), originalLines);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 2, unitPrice: 8500 };
  assert.equal(lineTotal(line), 17000);
});

test('lineTotal returns integer cents', () => {
  const line = { qty: 1, unitPrice: 6000 };
  assert.equal(lineTotal(line), 6000);
  assert.equal(Number.isInteger(lineTotal(line)), true);
});

test('lineTotal handles single unit', () => {
  const line = { qty: 1, unitPrice: 120000 };
  assert.equal(lineTotal(line), 120000);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, vatRate: 0 },
      { qty: 5, unitPrice: 9500, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 64500, discount: 0, vat: 0, total: 64500 });
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 3, unitPrice: 6000, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 18000, discount: 0, vat: 0, total: 18000 });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 8500, vatRate: 0 },
      { qty: 2, unitPrice: 9500, vatRate: 0 },
      { qty: 3, unitPrice: 6000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 45500, discount: 0, vat: 0, total: 45500 });
});

test('invoiceTotals with an invoice from createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  assert.deepEqual(totals, { subtotal: 26500, discount: 0, total: 26500 });
});

test('invoiceTotals returns a new object', () => {
  const invoice = { lines: [{ qty: 1, unitPrice: 100 }] };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('addLine adds a new line to an invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 3);
  assert.equal(r2.value.lines[1].name, 'Development (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 5);
});

test('addLine validates qty is a positive integer', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };
  const r1 = addLine(invoice, { sku: 'DEV-HOUR', qty: 0 });
  assert.deepEqual(r1, { ok: false, error: 'QTY_INVALID' });

  const r2 = addLine(invoice, { sku: 'DEV-HOUR', qty: -1 });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });

  const r3 = addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 });
  assert.deepEqual(r3, { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU exists', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };
  const r = addLine(invoice, { sku: 'NOPE', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };
  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const original = JSON.stringify(r1.value);
  addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(JSON.stringify(r1.value), original);
});

test('removeLine removes a line from an invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  assert.equal(r1.ok, true);
  const r2 = removeLine(r1.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND for unknown SKU', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };
  const r = removeLine(invoice, 'NOPE');
  assert.deepEqual(r, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if removing the last line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };
  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  assert.equal(r1.ok, true);
  const original = JSON.stringify(r1.value);
  removeLine(r1.value, 'DES-HOUR');
  assert.equal(JSON.stringify(r1.value), original);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2024-0001');
  assert.equal(r2.value.status, 'issued');
});

test('issueInvoice generates the next number based on existing numbers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002'];
  const r2 = issueInvoice(r1.value, existingNumbers);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2024-0003');
});

test('issueInvoice handles multiple years', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r1.ok, true);
  const existingNumbers = ['INV-2024-0001', 'INV-2024-0002'];
  const r2 = issueInvoice(r1.value, existingNumbers);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2025-0001');
});

test('issueInvoice refuses to issue non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };
  const r = issueInvoice(invoice, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const original = JSON.stringify(r1.value);
  issueInvoice(r1.value, []);
  assert.equal(JSON.stringify(r1.value), original);
});

test('createInvoice accepts and preserves discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice applies tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery, standard tier (0%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0); // standard tier = 0%
});

test('createInvoice accepts decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice accepts 0 and 100 discount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  });
  assert.equal(r1.ok, true);
  assert.equal(r1.value.lines[0].discountPercent, 0);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 100 }],
  });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].discountPercent, 100);
});

test('createInvoice rejects discountPercent < 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: -1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects discountPercent > 100', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 101 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects non-numeric discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 'ten' }],
  });
  assert.deepEqual(r1, { ok: false, error: 'DISCOUNT_INVALID' });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: null }],
  });
  assert.deepEqual(r2, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('lineDiscount calculates discount amount', () => {
  const line = { qty: 2, unitPrice: 8500, discountPercent: 10 };
  assert.equal(lineDiscount(line), 1700);
});

test('lineDiscount defaults discountPercent to 0', () => {
  const line = { qty: 2, unitPrice: 8500 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount handles decimal discounts', () => {
  const line = { qty: 1, unitPrice: 1000, discountPercent: 12.5 };
  assert.equal(lineDiscount(line), 125);
});

test('lineDiscount rounds to nearest cent', () => {
  const line = { qty: 3, unitPrice: 8500, discountPercent: 33.33 };
  const discount = lineDiscount(line);
  assert.equal(discount, 8499);
});

test('lineDiscount returns 0 when discountPercent is 0', () => {
  const line = { qty: 5, unitPrice: 9500, discountPercent: 0 };
  assert.equal(lineDiscount(line), 0);
});

test('invoiceTotals includes discount field', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.total, 15300);
});

test('invoiceTotals sums discounts from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, discountPercent: 10 },
      { qty: 5, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 64500);
  assert.equal(totals.discount, 11200);
  assert.equal(totals.total, 53300);
});

test('invoiceTotals with mixed discount lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, discountPercent: 10 },
      { qty: 3, unitPrice: 6000, discountPercent: 0 },
      { qty: 1, unitPrice: 9500, discountPercent: 50 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 44500);
  assert.equal(totals.discount, 6450);
  assert.equal(totals.total, 38050);
});

test('invoiceTotals clamps total at 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 100 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns discount: 0 when no discounts', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 5, unitPrice: 9500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
});

test('addLine accepts discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine rejects invalid discountPercent', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };
  const r1 = addLine(invoice, { sku: 'DEV-HOUR', qty: 1, discountPercent: 101 });
  assert.deepEqual(r1, { ok: false, error: 'DISCOUNT_INVALID' });

  const r2 = addLine(invoice, { sku: 'DEV-HOUR', qty: 1, discountPercent: -5 });
  assert.deepEqual(r2, { ok: false, error: 'DISCOUNT_INVALID' });

  const r3 = addLine(invoice, { sku: 'DEV-HOUR', qty: 1, discountPercent: 'high' });
  assert.deepEqual(r3, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine applies tier discount when discountPercent not provided', () => {
  const r1 = createInvoice({
    customerId: 'C-002', // standard tier (0%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 0); // standard tier
});

test('addLine updates discountPercent when SKU already exists', () => {
  const r1 = createInvoice({
