  assert.equal(lines.length, 7);
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.match(lines[2], /2 × Design work \(hour\)/);
  assert.match(lines[3], /3 × Development \(hour\)/);
  assert.match(lines[4], /Subtotal:/);
  assert.match(lines[5], /VAT:/);
  assert.match(lines[6], /Total:/);
});

test('renderInvoiceText formats amounts correctly', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 5, discountPercent: 0 },
      { sku: 'STICKER', qty: 10, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  assert.match(text, /€9\.80/); // ICON-SET unit price
  assert.match(text, /€49\.00/); // 5 × 980
  assert.match(text, /€0\.50/); // STICKER unit price
  assert.match(text, /€5\.00/); // 10 × 50
  // Both have 21% VAT: 49*0.21 + 5*0.21 = 10.29 + 1.05 = 11.34
  assert.match(text, /Subtotal: €54\.00/);
  assert.match(text, /VAT: €11\.34/);
  assert.match(text, /Total: €65\.34/);
});

