      { sku: 'DES-HOUR', qty: 2 }, // no explicit discount, uses 5% tier
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  // lineTotal = 17000, discount = 850, after discount = 16150
  // VAT = 16150 * 21 / 100 = 3391.5 rounds to 3391 (banker's rounding: .5 rounds to nearest even = 3391 since it's odd, wait...)
  // Actually let me check: 16150 * 21 / 100 = 3391.5
  // With banker's rounding (round half to even): 3391.5 is exactly .5, so round to nearest even
  // 3391 is odd, 3392 is even, so round to 3392
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 850);
  assert.equal(totals.vat, 3392);
  assert.equal(totals.total, 18542);
});

